import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int k = Integer.parseInt(st.nextToken());int d = Integer.parseInt(st.nextToken());long MOD = 1000000007;long[][] dp = new long[n + 1][2];dp[0][0] = 1;for (int i = 1; i <= n; i++) {for (int j = 1; j <= k; j++) {if (i - j < 0) break;if (j < d) {dp[i][0] = (dp[i][0] + dp[i - j][0]) % MOD;dp[i][1] = (dp[i][1] + dp[i - j][1]) % MOD;} else {dp[i][1] = (dp[i][1] + dp[i - j][0] + dp[i - j][1]) % MOD;}}}System.out.println(dp[n][1]);}}